#define R iResolution.xy
float tiles(vec2 p) {
    vec2 t = mat2(1,1,1,-1)*p;
    vec2 r = round(t);
    float src = texture(iChannel1, r/64.).x;
    return step(0.3,abs(0.5-abs(dot(t-r,vec2(1.,sign(src-.5))))));
}
void mainImage(out vec4 O, in vec2 C){
    vec2 uv=(C-0.5*R)/R.x;
    float phi = atan(uv.y,uv.x);
    float r = length(uv)*.8;
    O = vec4(vec3(0.),1.);
    vec3 c = vec3(.8,.7,1.);
    float s = sin(iTime);
    for (float i = 0.; i <= fract(2.0*iTime); i+=.2) {
        float ri = floor(r*16.)/16.;
        phi = mod(phi + iTime * sin(41.0 * ri), 6.283);
        vec2 p = vec2(r,4.*.319*phi*ri);
        float text = step(0.35,textureLod(iChannel0,p,2.).x);
        float l1 = smoothstep(.005,0.0,abs(r+fract(5.*phi)*.003*fract(s*2.5)-ri-.005)) * 2.;
        float l2 = tiles(p * vec2(50.0,40.0));
        O.rgb += c * max(text + l1, l2) * step(0.063,r);
        c *= vec3(0.9+0.1*s*s,0.6 + 0.2*s,0.9);
        r *= 0.7 + 0.2 * s;
    }
    O.xyz = log(O.xyz+1.)-.8;
}
